package io.github.headmaster218.recorder.android;
import android.content.Context;import android.os.SystemClock;import io.github.headmaster218.recorder.core.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Real FTPS selected receipts; synthetic unrelated receipts only fill the history cap. */
public final class HistoricalWireClient {
 static int checks;static void yes(boolean v,String s){checks++;if(!v)throw new AssertionError(s);}
 static List<CommittedSegments.Entry> entries(CommittedSegments catalog)throws Exception{List<CommittedSegments.Entry> result=new ArrayList<>();String after=null;while(true){CommittedSegments.Page p=catalog.page(after);result.addAll(p.entries);if(!p.hasMore)return result;after=p.cursor();}}
 static Map<String,String> files(Path root)throws Exception{Map<String,String> out=new TreeMap<>();try(java.util.stream.Stream<Path> stream=Files.walk(root)){for(Path p:(Iterable<Path>)stream::iterator)if(Files.isRegularFile(p))out.put(root.relativize(p).toString(),FtpsQueue.digest(Files.readAllBytes(p)));}return out;}
 static FtpsTransfer.Result synthetic(CommittedSegments.Entry entry,FtpsQueue.Item item,String attempt)throws Exception{FtpsDelivery d=FtpsDelivery.encode(entry,item.revision,attempt);java.lang.reflect.Constructor<FtpsTransfer.Result> c=FtpsTransfer.Result.class.getDeclaredConstructor(long.class,String.class,String.class,String.class);c.setAccessible(true);return c.newInstance(item.bytes,item.wavHash,d.metadataSha256,d.markerSha256);}
 public static void main(String[]args)throws Exception{
  Path root=Paths.get(args[0]).toAbsolutePath();Context context=CatchupWireClient.context(root);Path spool=root.resolve("audio-spool");
  try(DirectorySpool store=new DirectorySpool(spool,new CachePolicy(32L*1024*1024,0),new DirectorySpool.NioProtocol(),(op,p)->{})){
   CaptureTimeline.Epoch epoch=new CaptureTimeline.Epoch("historical-fixture","run",0,new PcmFormat(8000,1),"mic","mic",CaptureTimeline.Gap.START);PcmSegmentWriter writer=new PcmSegmentWriter(store,epoch,8,0,p->{});byte[] pcm=new byte[501*16];writer.append(pcm,0,pcm.length);writer.stop();
  }
  CommittedSegments catalog=new CommittedSegments(spool);List<CommittedSegments.Entry> all=entries(catalog);yes(all.size()==501,"501 originals");Map<String,String> before=files(spool);
  FtpsQueue q=new FtpsQueue(context);FtpsQueue.Profile profile=q.save(new FtpsTransfer.Profile("127.0.0.1",Integer.parseInt(args[1]),"synthetic","/fixture"),null);q.automatic(profile.revision,"fixture explicit enrollment");
  for(int n=0;n<500;n++)yes(q.enqueue(all.get(n),profile.revision,true),"enqueued source");RealCoordinatorHarness h=new RealCoordinatorHarness(context,q);CatchupWireClient.transfer(h,context,2);
  List<FtpsQueue.Item> selected=new ArrayList<>(q.items(false).subList(0,2));List<String> receipts=new ArrayList<>();for(FtpsQueue.Item item:selected){yes(item.state.equals("VERIFIED_AT_TIME"),"selected genuinely readback verified");yes(!item.metadataHash.equals(item.resultMetadataHash),"transport envelope differs from local manifest");receipts.add(item.source+"\t"+item.attempt+"\t"+item.wavHash+"\t"+item.resultMetadataHash+"\t"+item.markerHash);}
  Files.write(root.resolve("genuine-receipts.tsv"),receipts,StandardCharsets.UTF_8);
  for(FtpsQueue.Item item:q.items(false)){if(item.state.equals("VERIFIED_AT_TIME"))continue;String attempt=FtpsTransfer.newAttemptName(item.source,item.wavHash,item.revision);q.begin(item,attempt);q.verified(item,synthetic(catalog.load(item.source),item,attempt));}
  yes(q.full()&&q.retirementCandidates().isEmpty(),"500 receipts fill capacity, no local cleanup");boolean refused=false;try{q.enqueue(all.get(500),profile.revision,true);}catch(java.io.IOException expected){refused=true;}yes(refused,"501st initially refused");
  boolean negative=args.length>2;
  if(negative){Path remote=Paths.get(args[2]);Files.delete(remote.resolve(selected.get(0).attempt).resolve("audio.wav"));Path corrupt=remote.resolve(selected.get(1).attempt).resolve("audio.wav");byte[] changed=Files.readAllBytes(corrupt);changed[changed.length-1]^=1;Files.write(corrupt,changed);}
  h.coordinator.cleanupEnabled(true,profile.revision);h.worker.drain();h.assertAvailable();yes(h.coordinator.requestHistoricalCleanup(profile.revision,selected,h.coordinator.cleanupConfirmationEpoch()),"controller accepted explicit exact selection");h.worker.drain();h.assertAvailable();for(FtpsQueue.Item item:q.items(false).subList(0,2))yes(item.cleanupState.equals("DEFERRED"),"controller persisted explicit selection");
  for(int n=0;n<2;n++){FtpsCoordinator.Job job=new FtpsCoordinator.Job();job.deadline=SystemClock.elapsedRealtime()+FtpsNetwork.ATTEMPT_MILLIS;h.runOne(job);h.assertAvailable();}
  if(negative){for(FtpsQueue.Item item:q.items(false).subList(0,2))yes(item.cleanupState.equals("BLOCKED"),"missing/corrupt exact remote attempt blocks cleanup");yes(q.retirementCandidates().isEmpty()&&q.full(),"failed readback cannot free capacity");yes(before.equals(files(spool)),"all501 original files preserved byte-for-byte");yes(entries(catalog).size()==501,"all501 sources intact");refused=false;try{q.enqueue(all.get(500),profile.revision,true);}catch(java.io.IOException expected){refused=true;}yes(refused,"501st still safely refused");yes(android.system.Os.openCount()==0,"no leaked directory descriptor");q.close();System.out.println("PASS historical negative missing/corrupt remote: "+checks+" assertions; 2 failed historical readbacks, no local deletion, no retirement, no capacity bypass");return;}
  List<FtpsQueue.Item> cleaned=q.items(false).subList(0,2);for(int n=0;n<2;n++){FtpsQueue.Item item=cleaned.get(n);yes(item.cleanupState.equals("REMOVED"),"actual cleanup removed selected original: "+item.cleanupState+" "+item.detail);yes(item.attempt.equals(selected.get(n).attempt),"same exact remote attempt reconciled");yes(!Files.exists(spool.resolve(item.source)),"selected ready object gone");}
  yes(q.retirementCandidates().size()==2,"only cleaned receipts eligible");RealCoordinatorHarness.set(h.coordinator,"retirementBlocked",false);h.invoke("retireHistory");h.assertAvailable();yes(!(Boolean)RealCoordinatorHarness.get(h.coordinator,"retirementBlocked"),"retirement not blocked: "+RealCoordinatorHarness.get(h.coordinator,"retirementNotice"));yes(q.items(false).size()==498&&!q.full(),"actual retirement frees two slots");
  for(FtpsQueue.Item item:selected){yes(q.retiredContains(item.source,item.revision),"dedup interval persisted");yes(!Files.exists(spool.resolve(item.source.substring(0,item.source.length()-6)+".retired")),"empty retired marker pruned");}
  h.invoke("prepareCatchup");yes(h.page()!=null&&h.page().size()==1,"only missed501st discovered");h.invoke("catchupOne");yes(q.items(false).size()==499&&q.contains(all.get(500).id,profile.revision),"actual catchup admits501st without reuploading retired sources");
  Map<String,String> after=files(spool);Set<String> removed=new HashSet<>();for(FtpsQueue.Item item:selected)removed.add(item.source+"/");for(Map.Entry<String,String> f:before.entrySet()){boolean selectedFile=false;for(String prefix:removed)if(f.getKey().startsWith(prefix))selectedFile=true;if(!selectedFile)yes(f.getValue().equals(after.get(f.getKey())),"unrelated original unchanged: "+f.getKey());}
  yes(entries(catalog).size()==499,"499 unrelated and not-yet-uploaded sources intact");yes(android.system.Os.openCount()==0,"all directory descriptors closed");yes(context.receiversReleased()&&context.connectivity.callbacksReleased(),"network observers released");
  q.close();q=new FtpsQueue(context);yes(q.items(false).size()==499&&q.retiredCount().equals("2"),"freed slots and retired history survive reopen");q.close();System.out.println("PASS historical real FTPS cleanup/retirement/admission: "+checks+" assertions; 2 real receipts/2 successful exact readbacks, 498 synthetic untouched history receipts");
 }
}
